static void merge(int* a, int* tmp, size_t left, size_t mid, size_t right) {
    size_t i = left, j = mid, k = left;
    while (i < mid && j < right) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
    }
    while (i < mid) tmp[k++] = a[i++];
    while (j < right) tmp[k++] = a[j++];
    for (size_t p = left; p < right; ++p) a[p] = tmp[p];
}

static void merge_sort_impl(int* a, int* tmp, size_t left, size_t right) {
    if (right - left <= 1) return;
    size_t mid = left + (right - left) / 2;
    merge_sort_impl(a, tmp, left, mid);
    merge_sort_impl(a, tmp, mid, right);
    merge(a, tmp, left, mid, right);
}

